static BUILTIN_SLICEBC_CACHE: OnceLock<RwLock<FxHashMap<usize, Arc<Vec<u8>>>>> = OnceLock::new();

#[inline]
fn eval_cached_builtin_snippet(
    snippet: &'static [u8],
    context: &mut boa_engine::Context,
) -> boa_engine::JsResult<BoaVal> {
    let key = snippet.as_ptr() as usize;
    let cache_lock = BUILTIN_SLICEBC_CACHE.get_or_init(|| RwLock::new(FxHashMap::default()));
    let cached_opt = {
        let r = cache_lock.read();
        r.get(&key).cloned()
    };
    let slicebc = match cached_opt {
        Some(arc) => arc,
        None => {
            let compiled = Arc::new(crate::js_preludes::compile_static_js_to_slicebc(snippet));
            cache_lock.write().insert(key, compiled.clone());
            compiled
        }
    };
    if !slicebc.is_empty() {
        if let Some(script) = boa_engine::Script::from_slicebc_bytes(&slicebc, context) {
            return script.evaluate(context);
        }
    }
    context.eval(boa_engine::Source::from_bytes(snippet))
}

