/// Returns the compile-time minified JS IIFE for a pre-fused `node:*` built-in module bit (`19..=28`)
/// in `shards_mask` so `build_fused_prelude_prefix` can embed referenced `node:*` modules directly
/// into `SLICEBC\x01` precompiled containers without runtime `eval_lazy_builtin_module` calls.
#[inline]
pub(crate) fn builtin_snippet_for_bit(bit: u32) -> &'static [u8] {
    match bit {
        19 => BUILTIN_CRYPTO_SNIPPET,
        20 => BUILTIN_FS_SNIPPET,
        21 => BUILTIN_PATH_SNIPPET,
        22 => BUILTIN_EVENTS_SNIPPET,
        23 => BUILTIN_OS_SNIPPET,
        24 => BUILTIN_UTIL_SNIPPET,
        25 => BUILTIN_ASSERT_SNIPPET,
        26 => BUILTIN_BUFFER_SNIPPET,
        27 => BUILTIN_URL_SNIPPET,
        28 => BUILTIN_TIMERS_SNIPPET,
        _ => b"",
    }
}
